.chip.best em { color: rgba(255,255,255,.72); }
.fixrow { display: flex; justify-content: flex-end; margin-top: 9px; }
.fix { height: 28px; padding: 0 14px; border: 0; border-radius: 99px; background: var(--amber-2); color: #3a2500; font: inherit; font-size: 13px; font-weight: 700; }
.list { background: var(--card); border: 1px solid var(--line); border-radius: 16px; overflow: hidden; }
.row { display: flex; align-items: center; gap: 11px; height: 46px; padding: 0 12px; border-top: 1px solid #f0e8d7; }
